1	//! inkseal 的库接口：对任意实现 [`std::io::Read`] 的输入计算 SHA-256 摘要。
2	//!
3	//! 摘要只取决于输入的原始字节，与命令行 `inkseal digest <文件>` 遵循同一内容规则。
4	
5	use sha2::{Digest, Sha256};
6	use std::error::Error;
7	use std::fmt;
8	use std::io::{self, Read};
9	
10	/// SHA-256 摘要结果，可表示为 64 个小写十六进制字符。
11	#[derive(Clone, Copy, PartialEq, Eq, Hash)]
12	pub struct Sha256Digest([u8; 32]);
13	
14	impl Sha256Digest {
15	    /// 返回摘要的原始 32 字节。
16	    pub fn as_bytes(&self) -> &[u8; 32] {
17	        &self.0
18	    }
19	
20	    /// 返回 64 个小写十六进制字符，与命令行输出一致（不含换行）。
21	    pub fn to_hex(&self) -> String {
22	        let mut hex = String::with_capacity(64);
23	        for byte in self.0 {
24	            hex.push(char::from_digit((byte >> 4) as u32, 16).unwrap());
25	            hex.push(char::from_digit((byte & 0x0f) as u32, 16).unwrap());
26	        }
27	        hex
28	    }
29	
30	    /// 从十六进制文本的原始字节解析摘要。
31	    ///
32	    /// 这是摘要文字还原的唯一规则：[`FromStr`] 只是在 `&str` 上委托给本
33	    /// 方法，命令行核对摘要时也直接使用它，因此从文本解析、按值比较与再次
34	    /// 显示永远遵循同一套规则。接受 `0-9`、`a-f` 和 `A-F`，大小写混用表示
35	    /// 同一个 32 字节值；解析结果可与 [`digest_reader`] 的结果直接比较，
36	    /// 再经 [`to_hex`](Self::to_hex) 显示时始终是完整的 64 个小写十六进制
37	    /// 字符，前导零不会丢失。
38	    ///
39	    /// 入参按原始字节处理，不要求是合法 UTF-8（例如操作系统给出的命令行
40	    /// 参数可能无法解码）：长度先按字节数判断，必须恰好为 64；长度正确时
41	    /// 报告首个非法字节从零开始的字节偏移。不做任何裁剪或修正，空白、末尾
42	    /// 换行、`0x` 前缀以及非 ASCII 字节都属于格式错误。
43	    pub fn from_hex_bytes(bytes: &[u8]) -> Result<Sha256Digest, ParseDigestError> {
44	        if bytes.len() != 64 {
45	            return Err(ParseDigestError::InvalidLength(bytes.len()));
46	        }
47	        let mut out = [0u8; 32];
48	        for (i, pair) in bytes.chunks_exact(2).enumerate() {
49	            let hi = hex_nibble(pair[0])
50	                .ok_or(ParseDigestError::InvalidHexChar(2 * i))?;
51	            let lo = hex_nibble(pair[1])
52	                .ok_or(ParseDigestError::InvalidHexChar(2 * i + 1))?;
53	            out[i] = (hi << 4) | lo;
54	        }
55	        Ok(Sha256Digest(out))
56	    }
57	}
58	
59	impl fmt::Display for Sha256Digest {
60	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
61	        f.write_str(&self.to_hex())
62	    }
63	}
64	
65	impl fmt::Debug for Sha256Digest {
66	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
67	        write!(f, "Sha256Digest({self})")
68	    }
69	}
70	
71	/// 从十六进制文本解析 [`Sha256Digest`] 失败时返回的类型化错误。
72	///
73	/// 两类失败可以按变体区分：长度不符时携带输入的实际 UTF-8 字节长度；
74	/// 长度正确但含非法字符时携带首个非法字节从零开始的字节偏移。
75	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
76	pub enum ParseDigestError {
77	    /// 输入的 UTF-8 字节长度不是 64；携带实际字节长度。
78	    InvalidLength(usize),
79	    /// 长度为 64 但含有非十六进制字符；携带首个非法字节的字节偏移
80	    /// （按原始文本的字节计算，不按字符个数）。
81	    InvalidHexChar(usize),
82	}
83	
84	impl ParseDigestError {
85	    /// 长度不符时返回输入的实际字节长度，否则返回 `None`。
86	    pub fn actual_length(&self) -> Option<usize> {
87	        match self {
88	            ParseDigestError::InvalidLength(len) => Some(*len),
89	            ParseDigestError::InvalidHexChar(_) => None,
90	        }
91	    }
92	
93	    /// 含非法字符时返回首个非法字节的字节偏移，否则返回 `None`。
94	    pub fn invalid_position(&self) -> Option<usize> {
95	        match self {
96	            ParseDigestError::InvalidLength(_) => None,
97	            ParseDigestError::InvalidHexChar(pos) => Some(*pos),
98	        }
99	    }
100	}
101	
102	impl fmt::Display for ParseDigestError {
103	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
104	        match self {
105	            ParseDigestError::InvalidLength(len) => write!(
106	                f,
107	                "digest must be exactly 64 ASCII hexadecimal characters, got {len} bytes"
108	            ),
109	            ParseDigestError::InvalidHexChar(pos) => {
110	                write!(f, "digest contains a non-hexadecimal byte at offset {pos}")
111	            }
112	        }
113	    }
114	}
115	
116	impl Error for ParseDigestError {}
117	
118	fn hex_nibble(b: u8) -> Option<u8> {
119	    match b {
120	        b'0'..=b'9' => Some(b - b'0'),
121	        b'a'..=b'f' => Some(b - b'a' + 10),
122	        b'A'..=b'F' => Some(b - b'A' + 10),
123	        _ => None,
124	    }
125	}
126	
127	impl std::str::FromStr for Sha256Digest {
128	    type Err = ParseDigestError;
129	
130	    /// 从 64 个 ASCII 十六进制字符解析摘要。
131	    ///
132	    /// 接受 `0-9`、`a-f` 和 `A-F`，大小写混用表示同一个摘要。输入必须
133	    /// 恰好是 64 个字符：不做任何裁剪或修正，空白、末尾换行、`0x` 前缀、
134	    /// 分隔符以及全角数字等非 ASCII 内容都属于格式错误。长度按输入的
135	    /// UTF-8 字节数判断，非法字符的位置也按字节偏移报告。
136	    fn from_str(s: &str) -> Result<Self, Self::Err> {
137	        Sha256Digest::from_hex_bytes(s.as_bytes())
138	    }
139	}
140	
141	/// 计算摘要过程中读取输入失败时返回的类型化错误。
142	#[derive(Debug)]
143	pub struct DigestError(io::Error);
144	
145	impl DigestError {
146	    /// 取出底层的 I/O 错误。
147	    pub fn into_inner(self) -> io::Error {
148	        self.0
149	    }
150	}
151	
152	impl fmt::Display for DigestError {
153	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
154	        write!(f, "failed to read input: {}", self.0)
155	    }
156	}
157	
158	impl Error for DigestError {
159	    fn source(&self) -> Option<&(dyn Error + 'static)> {
160	        Some(&self.0)
161	    }
162	}
163	
164	impl From<io::Error> for DigestError {
165	    fn from(err: io::Error) -> Self {
166	        DigestError(err)
167	    }
168	}
169	
170	/// 以流式方式读取 `reader` 的全部字节并计算 SHA-256 摘要。
171	///
172	/// 内存占用与输入大小无关。读取失败时返回 [`DigestError`]，绝不返回部分内容的摘要。
173	///
174	/// [`io::ErrorKind::Interrupted`] 是临时中断而非输入结束：本次读取没有
175	/// 消费任何字节，直接重试同一位置，摘要与未发生中断时完全一致。其他
176	/// 错误（权限不足、数据损坏等）仍然立即失败。
177	pub fn digest_reader<R: Read>(mut reader: R) -> Result<Sha256Digest, DigestError> {
178	    let mut hasher = Sha256::new();
179	    let mut buf = [0u8; 64 * 1024];
180	    loop {
181	        match reader.read(&mut buf) {
182	            Ok(0) => break,
183	            Ok(n) => hasher.update(&buf[..n]),
184	            Err(ref err) if err.kind() == io::ErrorKind::Interrupted => continue,
185	            Err(err) => return Err(DigestError(err)),
186	        }
187	    }
188	    Ok(Sha256Digest(hasher.finalize().into()))
189	}
