322	    /// 按脚本驱动的读取器：每个步骤要么返回下一段内容（长度可短于缓冲区），
323	    /// 要么返回一个错误。脚本用完后继续返回剩余内容，内容耗尽后返回 Ok(0)。
324	    /// 用于精确模拟“中断出现在任意位置”的读取序列。
325	    enum Step {
326	        /// 返回下一段内容（可为空切片以外的任意长度）。
327	        Data,
328	        /// 返回指定错误。
329	        Fail(io::ErrorKind, &'static str),
330	    }
331	
332	    struct ScriptedReader<'a> {
333	        data: &'a [u8],
334	        pos: usize,
335	        steps: &'a [Step],
336	        step_index: usize,
337	    }
338	
339	    impl<'a> ScriptedReader<'a> {
340	        fn new(data: &'a [u8], steps: &'a [Step]) -> Self {
341	            ScriptedReader { data, pos: 0, steps, step_index: 0 }
342	        }
343	    }
344	
345	    impl Read for ScriptedReader<'_> {
346	        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
347	            match self.steps.get(self.step_index) {
348	                Some(Step::Data) => {
349	                    self.step_index += 1;
350	                    // 每段最多给剩余内容的一半，保证一段脚本可能对应多次内容返回，
351	                    // 且片段长度通常短于缓冲区容量。
352	                    let remaining = self.data.len() - self.pos;
353	                    let n = (remaining / 2).max(1).min(remaining).min(buf.len());
354	                    buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
355	                    self.pos += n;
356	                    Ok(n)
357	                }
358	                Some(Step::Fail(kind, msg)) => {
359	                    self.step_index += 1;
360	                    Err(io::Error::new(*kind, *msg))
361	                }
362	                None => {
363	                    let remaining = self.data.len() - self.pos;
364	                    let n = remaining.min(buf.len());
365	                    buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
366	                    self.pos += n;
367	                    Ok(n)
368	                }
369	            }
370	        }
371	    }
372	
373	    use Step::{Data, Fail};
374	
375	    #[test]
376	    fn interrupted_reads_are_retried_not_treated_as_eof_or_error() {
377	        let data = long_input();
378	        let expected = digest_reader(&data[..]).unwrap();
379	
380	        // 第一个字节之前中断。
381	        let before_first = digest_reader(ScriptedReader::new(
382	            &data,
383	            &[Fail(io::ErrorKind::Interrupted, "EINTR"), Data, Data, Data, Data, Data, Data],
384	        ))
385	        .unwrap();
386	        // 中断夹在两段有效内容之间。
387	        let between = digest_reader(ScriptedReader::new(
388	            &data,
389	            &[Data, Fail(io::ErrorKind::Interrupted, "EINTR"), Data, Data, Data],
390	        ))
391	        .unwrap();
392	        // 最后一段内容之后、输入正式结束之前中断。
393	        let before_eof = digest_reader(ScriptedReader::new(
394	            &data,
395	            &[Data, Data, Data, Data, Data, Data, Fail(io::ErrorKind::Interrupted, "EINTR")],
396	        ))
397	        .unwrap();
398	        // 连续多次中断。
399	        let repeated = digest_reader(ScriptedReader::new(
400	            &data,
401	            &[
402	                Fail(io::ErrorKind::Interrupted, "EINTR"),
403	                Fail(io::ErrorKind::Interrupted, "EINTR"),
404	                Data,
405	                Fail(io::ErrorKind::Interrupted, "EINTR"),
406	                Fail(io::ErrorKind::Interrupted, "EINTR"),
407	                Data,
408	                Data,
409	                Data,
410	                Data,
411	                Fail(io::ErrorKind::Interrupted, "EINTR"),
412	                Fail(io::ErrorKind::Interrupted, "EINTR"),
413	            ],
414	        ))
415	        .unwrap();
416	
417	        for digest in [before_first, between, before_eof, repeated] {
418	            assert_eq!(digest, expected);
419	        }
420	        // 结果仍对应整份原始字节。
421	        assert_eq!(expected.to_hex(), LONG_INPUT_HEX);
422	    }
