435	    #[test]
436	    fn non_interrupted_error_after_interrupt_still_fails() {
437	        const PREFIX: &[u8] = b"partial bytes before the failure";
438	        // 先发生可恢复的临时中断，随后出现真正的读取错误：
439	        // 本次调用必须失败，且报告的是后来的真实错误，不是之前的中断。
440	        let err = digest_reader(ScriptedReader::new(
441	            PREFIX,
442	            &[
443	                Fail(io::ErrorKind::Interrupted, "EINTR"),
444	                Data,
445	                Fail(io::ErrorKind::PermissionDenied, "disk vanished"),
446	            ],
447	        ))
448	        .unwrap_err();
449	
450	        let inner = err.into_inner();
451	        assert_eq!(inner.kind(), io::ErrorKind::PermissionDenied);
452	        assert!(inner.to_string().contains("disk vanished"));
453	    }
