1	use inkseal::{ParseDigestError, Sha256Digest};
2	use std::env;
3	use std::ffi::OsStr;
4	use std::fs::File;
5	use std::io::{self, Write};
6	use std::path::Path;
7	use std::process::ExitCode;
8	
9	const USAGE: &str = "Usage: inkseal --version\n       inkseal digest <file>\n       inkseal check-digest <file> <digest>";
10	
11	fn main() -> ExitCode {
12	    // 使用 args_os 而非 args：命令行参数是操作系统给出的原始字节，
13	    // 在允许非 UTF-8 文件名的系统上这类路径是合法路径，必须原样保留。
14	    let mut args = env::args_os().skip(1);
15	    match args.next() {
16	        Some(ref cmd) if cmd.as_encoded_bytes() == b"--version" && args.next().is_none() => {
17	            emit_success(b"inkseal 0.1.0\n")
18	        }
19	        Some(ref cmd) if cmd.as_encoded_bytes() == b"digest" => {
20	            let (Some(path), None) = (args.next(), args.next()) else {
21	                eprintln!("{USAGE}");
22	                return ExitCode::from(2);
23	            };
24	            run_digest(Path::new(&path))
25	        }
26	        Some(ref cmd) if cmd.as_encoded_bytes() == b"check-digest" => {
27	            let (Some(path), Some(expected), None) = (args.next(), args.next(), args.next()) else {
28	                eprintln!("inkseal: check-digest requires exactly two arguments: <file> <digest>");
29	                eprintln!("{USAGE}");
30	                return ExitCode::from(2);
31	            };
32	            run_check_digest(Path::new(&path), &expected)
33	        }
34	        _ => {
35	            // 未知子命令（即便含有非 UTF-8 字节）等用法错误统一走这里。
36	            eprintln!("{USAGE}");
37	            ExitCode::from(2)
38	        }
39	    }
40	}
41	
42	fn run_digest(path: &Path) -> ExitCode {
43	    // 仅在输出错误信息时做损失性转换；打开文件始终使用原始路径，
44	    // 绝不把用于显示的文字当作实际路径访问。
45	    let display = path_display(path);
46	    let file = match File::open(path) {
47	        Ok(file) => file,
48	        Err(err) => {
49	            eprintln!("inkseal: cannot open '{display}': {err}");
50	            return ExitCode::FAILURE;
51	        }
52	    };
53	    match inkseal::digest_reader(file) {
54	        Ok(digest) => {
55	            let mut line = digest.to_hex();
56	            line.push('\n');
57	            emit_success(line.as_bytes())
58	        }
59	        Err(err) => {
60	            eprintln!("inkseal: cannot read '{display}': {err}");
61	            ExitCode::FAILURE
62	        }
63	    }
64	}
65	
66	/// 把成功结果一次性完整写到标准输出并立即刷出，返回进程退出码。
67	///
68	/// 成功的含义是**整行结果（含末尾换行）已经真正交到输出端**：仅算出
69	/// 摘要或通过比较并不构成成功，写中途失败或最后的刷新失败（例如标准
70	/// 输出被重定向到只读位置，或管道接收方提前关闭）都必须以退出码 1
71	/// 结束，而不是让 `println!` 的 panic 打印崩溃信息，也不能照常报成功。
72	///
73	/// 输出失败时只在标准错误给出一条以 `inkseal:` 开头的单行提示，保留
74	/// 系统给出的具体原因；不补充用法说明，不把摘要改写到标准错误，也不
75	/// 重试整行输出。标准输出此前可能已经收到结果的前几个字节，这些字节
76	/// 无法也不必撤回。若连这条提示都写不出去，同样静默地以退出码 1
77	/// 结束——报告输出失败的过程自身绝不能再崩溃。
78	fn emit_success(line: &[u8]) -> ExitCode {
79	    match write_stdout_all(line) {
80	        Ok(()) => ExitCode::SUCCESS,
81	        Err(err) => {
82	            // 直接走 Write trait 写原始字节，不经过会因写失败而 panic 的宏；
83	            // 提示本身写不出去也忽略，只需保证退出码为 1。
84	            let stderr = io::stderr();
85	            let mut err_handle = stderr.lock();
86	            let _ = writeln!(
87	                err_handle,
88	                "inkseal: unable to write to standard output: {err}"
89	            );
90	            let _ = err_handle.flush();
91	            ExitCode::FAILURE
92	        }
93	    }
94	}
95	
96	/// 直接对标准输出的原始文件描述符发起 `write`，绕过标准库 `Stdout`
97	/// 对“输出端不存在/拒绝写入”这类失败的特殊处理——它在某些情况下会把
