99	/// 调用方误以为结果已交付。短写照常续写到同一 fd；EINTR 立即重试。
100	#[cfg(unix)]
101	fn write_stdout_all(mut line: &[u8]) -> io::Result<()> {
102	    use std::os::raw::c_void;
103	    use std::os::fd::RawFd;
104	
105	    unsafe extern "C" {
106	        fn write(fd: RawFd, buf: *const c_void, count: usize) -> isize;
107	    }
108	
109	    const STDOUT_FD: RawFd = 1;
110	    while !line.is_empty() {
111	        let written = unsafe { write(STDOUT_FD, line.as_ptr().cast::<c_void>(), line.len()) };
112	        if written < 0 {
113	            let err = io::Error::last_os_error();
114	            // 临时中断不代表任何字节的命运，原地重试。
115	            if err.kind() == io::ErrorKind::Interrupted {
116	                continue;
117	            }
118	            return Err(err);
119	        }
120	        let n = written as usize;
121	        if n == 0 {
122	            // 对正数计数的 write 返回 0 没有可恢复的含义，按写出失败处理，
123	            // 避免在此空转。
124	            return Err(io::Error::new(
125	                io::ErrorKind::WriteZero,
126	                "write to standard output returned no progress",
127	            ));
128	        }
129	        line = &line[n..];
130	    }
131	    Ok(())
132	}
133	
134	/// 非 Unix 目标：标准库句柄不存在上述特殊处理，沿用加锁写入并显式刷新。
135	#[cfg(not(unix))]
136	fn write_stdout_all(line: &[u8]) -> io::Result<()> {
137	    let stdout = io::stdout();
138	    let mut handle = stdout.lock();
139	    handle.write_all(line)?;
140	    handle.flush()
141	}
