143	/// 解析用户给出的预期摘要。
144	///
145	/// 解析规则完全来自库（[`Sha256Digest::from_hex_bytes`]），与库的
146	/// `FromStr` 以及摘要的再次显示共用同一套实现：必须恰好是 64 个 ASCII
147	/// 十六进制字符（大小写均可），按其表示的 32 字节摘要值比较，不做任何
148	/// 空白裁剪——前缀、空格、末尾换行、长度不对或含非十六进制字符都视为
149	/// 格式错误；参数无法解码为合法文字时，直接按其原始字节校验，同样视为
150	/// 格式错误。这里只负责把库的类型化错误映射为本命令既有的提示文字。
151	fn parse_expected_digest(arg: &OsStr) -> Result<Sha256Digest, String> {
152	    Sha256Digest::from_hex_bytes(arg.as_encoded_bytes()).map_err(|err| match err {
153	        ParseDigestError::InvalidLength(len) => format!(
154	            "expected digest must be exactly 64 ASCII hexadecimal characters, got {len}"
155	        ),
156	        ParseDigestError::InvalidHexChar(_) => {
157	            "expected digest contains a non-hexadecimal character".to_string()
158	        }
159	    })
160	}
161	
162	fn run_check_digest(path: &Path, expected_arg: &OsStr) -> ExitCode {
163	    // 先校验摘要格式；格式不合法时绝不打开文件——即使路径本身也不存在，
164	    // 仍报告摘要格式问题。
165	    let expected = match parse_expected_digest(expected_arg) {
166	        Ok(digest) => digest,
167	        Err(reason) => {
168	            eprintln!("inkseal: invalid expected digest: {reason}");
169	            eprintln!("{USAGE}");
170	            return ExitCode::from(2);
171	        }
172	    };
173	
174	    // 仅在输出错误信息时做损失性转换；打开文件始终使用原始路径，
175	    // 绝不把用于显示的文字当作实际路径访问。
176	    let display = path_display(path);
177	    let file = match File::open(path) {
178	        Ok(file) => file,
179	        Err(err) => {
180	            eprintln!("inkseal: cannot open '{display}': {err}");
181	            return ExitCode::FAILURE;
182	        }
183	    };
184	    let actual = match inkseal::digest_reader(file) {
185	        Ok(digest) => digest,
186	        Err(err) => {
187	            eprintln!("inkseal: cannot read '{display}': {err}");
188	            return ExitCode::FAILURE;
189	        }
190	    };
191	
192	    if actual == expected {
193	        emit_success(b"OK\n")
194	    } else {
195	        // 内容不匹配：预期与实际都用库的同一显示规则呈现为
196	        // 64 个小写十六进制字符（大小写混用的输入也规范为小写）。
197	        eprintln!("inkseal: digest mismatch for '{display}'");
198	        eprintln!("expected: {}", expected.to_hex());
199	        eprintln!("actual:   {}", actual.to_hex());
