619	#[test]
620	fn check_digest_non_utf8_digest_argument_is_usage_error_without_opening_file() {
621	    use std::os::unix::ffi::OsStrExt;
622	    let dir = TestDir::new("check-non-utf8-digest");
623	    let missing = dir.path().join("does-not-exist");
624	
625	    // 长度恰好 64 字节，但含无法解码为合法文字的字节：属于用法错误，
