635	// ── 标准输出写入失败 ─────────────────────────────────────────────────────────
636	
637	#[cfg(unix)]
638	mod output_failures {
639	    use super::*;
640	    use std::fs::OpenOptions;
641	    use std::os::unix::io::{FromRawFd, RawFd};
642	    use std::process::Stdio;
643	
644	    unsafe extern "C" {
645	        fn pipe(pipefd: *mut RawFd) -> std::os::raw::c_int;
646	    }
647	
648	    /// 构造一个读端已经关闭的管道写端：子进程一写标准输出就收到 EPIPE，
649	    /// 模拟“结果交给管道而接收方已提前关闭”。
650	    fn closed_pipe_stdout() -> Stdio {
651	        let mut fds: [RawFd; 2] = [-1, -1];
652	        assert_eq!(unsafe { pipe(fds.as_mut_ptr()) }, 0);
653	        // 读端立即关闭（File 析构关闭该 fd）。
654	        drop(unsafe { std::fs::File::from_raw_fd(fds[0]) });
655	        Stdio::from(unsafe { std::fs::File::from_raw_fd(fds[1]) })
656	    }
657	
658	    /// 以读不开写方式打开一个普通文件得到的 fd：对它写入会被内核拒绝，
659	    /// 模拟“标准输出被重定向到拒绝写入的位置”。
660	    fn read_only_stdout(path: &Path) -> Stdio {
661	        let file = OpenOptions::new()
662	            .read(true)
663	            .write(false)
664	            .open(path)
665	            .expect("open read-only fd");
666	        Stdio::from(file)
667	    }
668	
669	    fn run_with_stdout(stdout: Stdio, args: &[&OsStr]) -> Output {
670	        inkseal()
671	            .args(args)
672	            .stdout(stdout)
673	            .output()
674	            .expect("failed to run inkseal")
675	    }
676	
677	    /// 输出失败的完整约定：退出码 1、标准输出为空、标准错误只有一条
678	    /// inkseal: 的写入失败提示（保留系统原因），没有任何崩溃信息。
679	    fn assert_output_failure(output: &Output) -> String {
680	        assert_eq!(output.status.code(), Some(1), "exit code: {output:?}");
681	        assert!(
682	            output.stdout.is_empty(),
683	            "captured stdout must be empty: {:?}",
684	            String::from_utf8_lossy(&output.stdout)
685	        );
686	        let stderr = String::from_utf8(output.stderr.clone()).expect("stderr must be UTF-8");
687	        assert!(
688	            stderr.starts_with("inkseal: unable to write to standard output"),
689	            "must report an output failure, not another error: {stderr:?}"
690	        );
691	        assert!(
692	            stderr.ends_with('\n') && !stderr[..stderr.len() - 1].contains('\n'),
693	            "hint must be a single line: {stderr:?}"
694	        );
695	        // 系统给出的具体原因必须保留，且不能是 Rust 崩溃信息。
696	        assert!(!stderr.contains("panicked"), "must not crash: {stderr:?}");
697	        stderr
698	    }
699	
700	    #[test]
701	    fn version_write_failure_exits_1_without_panic() {
702	        let output = run_with_stdout(closed_pipe_stdout(), &[OsStr::new("--version")]);
703	
704	        let stderr = assert_output_failure(&output);
705	        assert!(stderr.to_lowercase().contains("pipe"), "keep OS reason: {stderr:?}");
706	    }
707	
708	    #[test]
709	    fn digest_computed_but_not_delivered_is_still_a_failure() {
710	        let dir = TestDir::new("digest-dead-pipe");
711	        let path = dir.write_file(OsStr::new("hello.txt"), b"abc");
712	
713	        let output = run_with_stdout(
714	            closed_pipe_stdout(),
715	            &[OsStr::new("digest"), path.as_os_str()],
716	        );
717	
718	        let stderr = assert_output_failure(&output);
719	        // 不能把输出问题误报成读文件问题，也不能把摘要写到标准错误。
720	        assert!(!stderr.contains("cannot read"), "{stderr:?}");
721	        assert!(!stderr.contains(ABC_HEX), "digest must not move to stderr: {stderr:?}");
722	    }
723	
724	    #[test]
725	    fn check_digest_match_but_not_delivered_is_still_a_failure() {
726	        let dir = TestDir::new("check-dead-pipe");
727	        let path = dir.write_file(OsStr::new("hello.txt"), b"abc");
728	
729	        let output = run_with_stdout(
730	            closed_pipe_stdout(),
731	            &[
732	                OsStr::new("check-digest"),
733	                path.as_os_str(),
734	                OsStr::new(ABC_HEX),
735	            ],
736	        );
737	
738	        let stderr = assert_output_failure(&output);
739	        // 不能补写成功标记，也不能误报为不匹配。
740	        assert!(!stderr.to_lowercase().contains("mismatch"), "{stderr:?}");
741	        assert!(!stderr.contains("OK"), "must not echo success marker to stderr: {stderr:?}");
742	    }
743	
744	    #[test]
745	    fn redirect_to_unwritable_destination_is_output_failure() {
746	        let dir = TestDir::new("stdout-readonly");
747	        let target = dir.write_file(OsStr::new("sink"), b"");
748	
749	        let output = run_with_stdout(
750	            read_only_stdout(&target),
751	            &[OsStr::new("--version")],
752	        );
753	
754	        // 只读 fd 上的写入同样是输出失败，而非崩溃或成功。
755	        assert_output_failure(&output);
756	    }
757	
758	    #[test]
759	    fn failure_branches_are_not_reported_as_output_errors_when_stdout_dead() {
760	        let dir = TestDir::new("dead-stdout-failures");
761	        let file = dir.write_file(OsStr::new("hello.txt"), b"abc");
762	        let missing = dir.path().join("nope.txt");
763	        let empty_hex = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";
764	
765	        // 参数错误仍是退出码 2 与用法提示。
766	        let usage = run_with_stdout(closed_pipe_stdout(), &[OsStr::new("digest")]);
767	        assert_eq!(usage.status.code(), Some(2), "{usage:?}");
768	        let stderr = String::from_utf8_lossy(&usage.stderr);
769	        assert!(stderr.contains("Usage:"), "{stderr:?}");
770	        assert!(!stderr.contains("unable to write to standard output"), "{stderr:?}");
771	
772	        // 摘要格式错误仍是退出码 2，且不访问文件。
773	        let bad_digest = run_with_stdout(
774	            closed_pipe_stdout(),
775	            &[
776	                OsStr::new("check-digest"),
777	                missing.as_os_str(),
778	                OsStr::new("abc"),
779	            ],
780	        );
781	        assert_eq!(bad_digest.status.code(), Some(2), "{bad_digest:?}");
782	        let stderr = String::from_utf8_lossy(&bad_digest.stderr);
783	        assert!(stderr.contains("Usage:"), "{stderr:?}");
784	        assert!(!stderr.contains("unable to write to standard output"), "{stderr:?}");
785	
786	        // 文件打不开仍是退出码 1 与 cannot open，不是输出错误。
787	        let open_fail = run_with_stdout(
788	            closed_pipe_stdout(),
789	            &[OsStr::new("digest"), missing.as_os_str()],
790	        );
791	        assert_eq!(open_fail.status.code(), Some(1), "{open_fail:?}");
792	        let stderr = assert_failure(&open_fail);
793	        assert!(stderr.contains("cannot open"), "{stderr:?}");
794	        assert!(!stderr.contains("unable to write to standard output"), "{stderr:?}");
795	
796	        // 内容不匹配仍按不匹配报告：没有成功结果需要写出，
797	        // 不应仅因标准输出不可用而变成输出错误。
798	        let mismatch = run_with_stdout(
799	            closed_pipe_stdout(),
800	            &[
801	                OsStr::new("check-digest"),
802	                file.as_os_str(),
803	                OsStr::new(empty_hex),
804	            ],
805	        );
806	        assert_mismatch(&mismatch, empty_hex, ABC_HEX);
807	        let stderr = String::from_utf8_lossy(&mismatch.stderr);
808	        assert!(!stderr.contains("unable to write to standard output"), "{stderr:?}");
809	    }
810	}
