        Ok(file) => file,
        Err(err) => {
            return emit_error(
                1,
                format!("inkseal: cannot open '{display}': {err}\n").as_bytes(),
            );
        }
    };
    match inkseal::digest_reader(file) {
        Ok(digest) => {
            let mut line = digest.to_hex();
            line.push('\n');
