1	use inkseal::{ParseDigestError, Sha256Digest};
2	use std::env;
3	use std::ffi::OsStr;
4	use std::fs::File;
5	use std::io;
6	use std::path::Path;
7	use std::process::ExitCode;
8	
9	const USAGE: &str = "Usage: inkseal --version\n       inkseal digest <file>\n       inkseal check-digest <file> <digest>";
10	
11	fn main() -> ExitCode {
12	    // 使用 args_os 而非 args：命令行参数是操作系统给出的原始字节，
13	    // 在允许非 UTF-8 文件名的系统上这类路径是合法路径，必须原样保留。
14	    let mut args = env::args_os().skip(1);
15	    match args.next() {
16	        Some(ref cmd) if cmd.as_encoded_bytes() == b"--version" && args.next().is_none() => {
17	            emit_success(b"inkseal 0.1.0\n")
18	        }
19	        Some(ref cmd) if cmd.as_encoded_bytes() == b"digest" => {
20	            let (Some(path), None) = (args.next(), args.next()) else {
21	                return emit_error(2, format!("{USAGE}\n").as_bytes());
22	            };
23	            run_digest(Path::new(&path))
24	        }
25	        Some(ref cmd) if cmd.as_encoded_bytes() == b"check-digest" => {
26	            let (Some(path), Some(expected), None) = (args.next(), args.next(), args.next()) else {
27	                return emit_error(
28	                    2,
29	                    format!(
30	                        "inkseal: check-digest requires exactly two arguments: <file> <digest>\n\
31	                         {USAGE}\n"
32	                    )
33	                    .as_bytes(),
34	                );
35	            };
36	            run_check_digest(Path::new(&path), &expected)
37	        }
38	        _ => {
39	            // 未知子命令（即便含有非 UTF-8 字节）等用法错误统一走这里。
40	            emit_error(2, format!("{USAGE}\n").as_bytes())
41	        }
42	    }
43	}
44	
45	fn run_digest(path: &Path) -> ExitCode {
46	    // 仅在输出错误信息时做损失性转换；打开文件始终使用原始路径，
47	    // 绝不把用于显示的文字当作实际路径访问。
48	    let display = path_display(path);
49	    let file = match File::open(path) {
50	        Ok(file) => file,
51	        Err(err) => {
52	            return emit_error(
53	                1,
54	                format!("inkseal: cannot open '{display}': {err}\n").as_bytes(),
55	            );
56	        }
57	    };
58	    match inkseal::digest_reader(file) {
59	        Ok(digest) => {
60	            let mut line = digest.to_hex();
61	            line.push('\n');
62	            emit_success(line.as_bytes())
63	        }
64	        Err(err) => emit_error(
65	            1,
66	            format!("inkseal: cannot read '{display}': {err}\n").as_bytes(),
67	        ),
68	    }
69	}
70	
71	/// 把成功结果一次性完整写到标准输出并立即刷出，返回进程退出码。
72	///
73	/// 成功的含义是**整行结果（含末尾换行）已经真正交到输出端**：仅算出
74	/// 摘要或通过比较并不构成成功，写中途失败或最后的刷新失败（例如标准
75	/// 输出被重定向到只读位置，或管道接收方提前关闭）都必须以退出码 1
76	/// 结束，而不是让 `println!` 的 panic 打印崩溃信息，也不能照常报成功。
77	///
78	/// 输出失败时只在标准错误给出一条以 `inkseal:` 开头的单行提示，保留
79	/// 系统给出的具体原因；不补充用法说明，不把摘要改写到标准错误，也不
80	/// 重试整行输出。标准输出此前可能已经收到结果的前几个字节，这些字节
81	/// 无法也不必撤回。若连这条提示都写不出去，同样静默地以退出码 1
82	/// 结束——报告输出失败的过程自身绝不能再崩溃。
83	fn emit_success(line: &[u8]) -> ExitCode {
84	    match write_stdout_all(line) {
85	        Ok(()) => ExitCode::SUCCESS,
86	        Err(err) => {
87	            // 与失败路径同一条规则：提示本身写不出去也忽略，只需保证
88	            // 退出码为 1，绝不经过会因写失败而 panic 的宏。
89	            let hint = format!("inkseal: unable to write to standard output: {err}\n");
90	            let _ = write_stderr_all(hint.as_bytes());
91	            ExitCode::FAILURE
92	        }
93	    }
94	}
95	
96	/// 失败路径的统一出口：把既有的错误提示（原始字节，含其行结构）尽力
97	/// 写到标准错误，然后以约定的退出码（用法错误 `2`、其余失败 `1`）结束。
98	///
99	/// 提示说明的是**已经发生的失败**：接收方是否还读得到提示，不能改变
100	/// 命令对本次操作的判断。标准错误被接到另一个程序而接收方提前关闭管道、
101	/// 或从一开始就拒绝写入时，`eprintln!` 会在 EPIPE/EBADF 上 panic，使
102	/// 进程以崩溃退出码（101）结束并打出崩溃信息，丢掉原本约定的退出码。
103	/// 这里与 [emit_success] 一样直接走 `write` 系统调用并忽略写失败：
104	/// 已经送出的字节保留，写不出去的部分不补齐、不重试、不改写到标准输出，
105	/// 只保证静默地以 `code` 正常结束。
106	fn emit_error(code: u8, message: &[u8]) -> ExitCode {
107	    let _ = write_stderr_all(message);
108	    ExitCode::from(code)
109	}
110	
111	/// 直接对标准错误的原始文件描述符发起 `write`，绕过标准库 `Stderr`
112	/// 的行缓冲以及 `eprintln!`/`writeln!` 在写失败时的 panic（宏内部
113	/// `unwrap`）。短写照常续写到同一 fd；EINTR 立即重试。任何无法继续
114	/// 写入的错误都返回，由调用方决定忽略——失败提示本身绝不能再崩溃。
115	#[cfg(unix)]
116	fn write_stderr_all(mut message: &[u8]) -> io::Result<()> {
117	    use std::os::raw::c_void;
118	    use std::os::fd::RawFd;
119	
120	    unsafe extern "C" {
121	        fn write(fd: RawFd, buf: *const c_void, count: usize) -> isize;
122	    }
123	
124	    const STDERR_FD: RawFd = 2;
125	    while !message.is_empty() {
126	        let written = unsafe { write(STDERR_FD, message.as_ptr().cast::<c_void>(), message.len()) };
127	        if written < 0 {
128	            let err = io::Error::last_os_error();
129	            // 临时中断不代表任何字节的命运，原地重试。
130	            if err.kind() == io::ErrorKind::Interrupted {
131	                continue;
132	            }
133	            return Err(err);
134	        }
135	        let n = written as usize;
136	        if n == 0 {
137	            // 对正数计数的 write 返回 0 没有可恢复的含义，停止续写，
138	            // 避免在此空转。
139	            return Err(io::Error::new(
140	                io::ErrorKind::WriteZero,
141	                "write to standard error returned no progress",
142	            ));
143	        }
144	        message = &message[n..];
145	    }
146	    Ok(())
147	}
148	
149	/// 非 Unix 目标：沿用加锁写入并显式刷新；写失败同样由调用方忽略。
150	#[cfg(not(unix))]
151	fn write_stderr_all(message: &[u8]) -> io::Result<()> {
152	    use std::io::Write;
153	
154	    let stderr = io::stderr();
155	    let mut handle = stderr.lock();
156	    handle.write_all(message)?;
157	    handle.flush()
158	}
159	
160	/// 直接对标准输出的原始文件描述符发起 `write`，绕过标准库 `Stdout`
161	/// 对“输出端不存在/拒绝写入”这类失败的特殊处理——它在某些情况下会把
162	/// 失败（如 fd 以只读方式打开时内核返回的 EBADF）静默报告为成功，导致
163	/// 调用方误以为结果已交付。短写照常续写到同一 fd；EINTR 立即重试。
164	#[cfg(unix)]
165	fn write_stdout_all(mut line: &[u8]) -> io::Result<()> {
166	    use std::os::raw::c_void;
167	    use std::os::fd::RawFd;
168	
169	    unsafe extern "C" {
170	        fn write(fd: RawFd, buf: *const c_void, count: usize) -> isize;
171	    }
172	
173	    const STDOUT_FD: RawFd = 1;
174	    while !line.is_empty() {
175	        let written = unsafe { write(STDOUT_FD, line.as_ptr().cast::<c_void>(), line.len()) };
176	        if written < 0 {
177	            let err = io::Error::last_os_error();
178	            // 临时中断不代表任何字节的命运，原地重试。
179	            if err.kind() == io::ErrorKind::Interrupted {
180	                continue;
181	            }
182	            return Err(err);
183	        }
184	        let n = written as usize;
185	        if n == 0 {
186	            // 对正数计数的 write 返回 0 没有可恢复的含义，按写出失败处理，
187	            // 避免在此空转。
188	            return Err(io::Error::new(
189	                io::ErrorKind::WriteZero,
190	                "write to standard output returned no progress",
191	            ));
192	        }
193	        line = &line[n..];
194	    }
195	    Ok(())
196	}
197	
198	/// 非 Unix 目标：标准库句柄不存在上述特殊处理，沿用加锁写入并显式刷新。
199	#[cfg(not(unix))]
200	fn write_stdout_all(line: &[u8]) -> io::Result<()> {
201	    use std::io::Write;
202	
203	    let stdout = io::stdout();
204	    let mut handle = stdout.lock();
205	    handle.write_all(line)?;
206	    handle.flush()
207	}
208	
209	/// 解析用户给出的预期摘要。
210	///
211	/// 解析规则完全来自库（[`Sha256Digest::from_hex_bytes`]），与库的
212	/// `FromStr` 以及摘要的再次显示共用同一套实现：必须恰好是 64 个 ASCII
213	/// 十六进制字符（大小写均可），按其表示的 32 字节摘要值比较，不做任何
214	/// 空白裁剪——前缀、空格、末尾换行、长度不对或含非十六进制字符都视为
215	/// 格式错误；参数无法解码为合法文字时，直接按其原始字节校验，同样视为
216	/// 格式错误。这里只负责把库的类型化错误映射为本命令既有的提示文字。
217	fn parse_expected_digest(arg: &OsStr) -> Result<Sha256Digest, String> {
218	    Sha256Digest::from_hex_bytes(arg.as_encoded_bytes()).map_err(|err| match err {
219	        ParseDigestError::InvalidLength(len) => format!(
220	            "expected digest must be exactly 64 ASCII hexadecimal characters, got {len}"
221	        ),
222	        ParseDigestError::InvalidHexChar(_) => {
223	            "expected digest contains a non-hexadecimal character".to_string()
224	        }
225	    })
226	}
227	
228	fn run_check_digest(path: &Path, expected_arg: &OsStr) -> ExitCode {
229	    // 先校验摘要格式；格式不合法时绝不打开文件——即使路径本身也不存在，
230	    // 仍报告摘要格式问题。
231	    let expected = match parse_expected_digest(expected_arg) {
232	        Ok(digest) => digest,
233	        Err(reason) => {
234	            return emit_error(
235	                2,
236	                format!("inkseal: invalid expected digest: {reason}\n{USAGE}\n").as_bytes(),
237	            );
238	        }
239	    };
240	
241	    // 仅在输出错误信息时做损失性转换；打开文件始终使用原始路径，
242	    // 绝不把用于显示的文字当作实际路径访问。
243	    let display = path_display(path);
244	    let file = match File::open(path) {
245	        Ok(file) => file,
246	        Err(err) => {
247	            return emit_error(
248	                1,
249	                format!("inkseal: cannot open '{display}': {err}\n").as_bytes(),
250	            );
251	        }
252	    };
253	    let actual = match inkseal::digest_reader(file) {
254	        Ok(digest) => digest,
255	        Err(err) => {
256	            return emit_error(
257	                1,
258	                format!("inkseal: cannot read '{display}': {err}\n").as_bytes(),
259	            );
260	        }
261	    };
262	
263	    if actual == expected {
264	        emit_success(b"OK\n")
265	    } else {
266	        // 内容不匹配：预期与实际都用库的同一显示规则呈现为
267	        // 64 个小写十六进制字符（大小写混用的输入也规范为小写）。
268	        emit_error(
269	            1,
270	            format!(
271	                "inkseal: digest mismatch for '{display}'\n\
272	                 expected: {}\n\
273	                 actual:   {}\n",
274	                expected.to_hex(),
275	                actual.to_hex()
276	            )
277	            .as_bytes(),
278	        )
279	    }
280	}
281	
282	/// 生成可安全输出到标准错误的路径文本：不可解码的字节以替换字符
283	/// （U+FFFD）呈现，控制字符转义为可见写法。该文本只用于显示。
284	fn path_display(path: &Path) -> String {
285	    let lossy = path.to_string_lossy();
286	    if !lossy.contains(char::is_control) {
287	        return lossy.into_owned();
288	    }
289	    let mut out = String::with_capacity(lossy.len());
290	    for ch in lossy.chars() {
291	        match ch {
292	            '\t' => out.push_str("\\t"),
293	            '\n' => out.push_str("\\n"),
294	            '\r' => out.push_str("\\r"),
295	            c if c.is_control() => {
296	                use std::fmt::Write as _;
297	                let _ = write!(out, "\\u{{{:x}}}", c as u32);
298	            }
299	            c => out.push(c),
300	        }
301	    }
302	    out
303	}
304

